package com.example.todo.service; import com.example.todo.dto.*; import com.example.todo.entity.*; import com.example.todo.exception.TodoNotFoundException; import com.example.todo.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.security.core.userdetails.UsernameNotFoundException; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class TodoService {private final TodoRepository todos;private final UserRepository users; public Page<TodoResponse> findAll(String u,int page,int size,String search,Boolean completed){User user=user(u);Pageable p=PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100),Sort.by(Sort.Direction.DESC,"id"));String s=search==null?"":search.trim();Page<Todo>x;if(completed!=null&&!s.isBlank())x=todos.findByUserAndCompletedAndTitleContainingIgnoreCase(user,completed,s,p);else if(completed!=null)x=todos.findByUserAndCompleted(user,completed,p);else if(!s.isBlank())x=todos.findByUserAndTitleContainingIgnoreCase(user,s,p);else x=todos.findByUser(user,p);return x.map(this::out);} public TodoResponse one(Long id,String u){return out(get(id,u));} public TodoResponse create(TodoRequest r,String u){return out(todos.save(Todo.builder().title(r.title()).description(r.description()).completed(false).user(user(u)).build()));} public TodoResponse update(Long id,TodoRequest r,String u){Todo t=get(id,u);t.setTitle(r.title());t.setDescription(r.description());return out(todos.save(t));} public TodoResponse toggle(Long id,String u){Todo t=get(id,u);t.setCompleted(!t.isCompleted());return out(todos.save(t));} public void delete(Long id,String u){todos.delete(get(id,u));} private Todo get(Long id,String u){User x=user(u);return todos.findById(id).filter(t->t.getUser().getId().equals(x.getId())).orElseThrow(()->new TodoNotFoundException(id));} private User user(String u){return users.findByUsername(u).orElseThrow(()->new UsernameNotFoundException("User not found"));} private TodoResponse out(Todo t){return new TodoResponse(t.getId(),t.getTitle(),t.getDescription(),t.isCompleted());}}
